using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
using System.Collections.Generic;

/// <summary>
/// One-shot editor script: creates 8-direction run animation clips from the run.png
/// sprite sheet, updates the Flynn_FrameAnimator controller BlendTrees, and
/// assigns the normal map to the character material.
/// Run via: Menu → Tools → Setup 8-Dir Run   (then delete this script).
/// </summary>
public static class Setup8DirRun
{
    private const string SpriteSheetPath = "Assets/Flynn/Sprites/run.png";
    private const string NormalMapPath   = "Assets/Flynn/Sprites/run_n.png";
    private const string AnimFolder      = "Assets/Flynn/Animations/Run8Dir";
    private const string ControllerPath  = "Assets/Flynn/Animations/Flynn_FrameAnimator.controller";
    private const string MaterialPath    = "Assets/Flynn/Materials/M_SpriteLit3D.mat";

    // FacingDir values (must match FlynnAnimationDriver)
    private const int DIR_DOWN       = 0;
    private const int DIR_DOWNLEFT   = 1;
    private const int DIR_LEFT       = 2;
    private const int DIR_UPLEFT     = 3;
    private const int DIR_UP         = 4;
    private const int DIR_UPRIGHT    = 5;
    private const int DIR_RIGHT      = 6;
    private const int DIR_DOWNRIGHT  = 7;

    // Row order in the sprite sheet: Down, DownLeft, Left, UpLeft, Up, UpRight, Right, DownRight
    private static readonly string[] DirectionNames = new[]
    {
        "Down", "DownLeft", "Left", "UpLeft", "Up", "UpRight", "Right", "DownRight"
    };

    // Which existing 3-dir animation to reuse for each diagonal in non-run trees
    // 0=Down, 4=Up, 2=Left   (index into the old 3-clip arrays)
    private static readonly int[] DiagonalFallbackIndex = new[]
    {
        0, // Down       → Down clip
        0, // DownLeft   → Down clip
        2, // Left       → Left clip
        2, // UpLeft     → Left clip
        1, // Up         → Up clip
        1, // UpRight    → Up clip
        2, // Right      → Left clip (driver will flipX)
        0, // DownRight  → Down clip
    };

    [MenuItem("Tools/Setup 8-Dir Run")]
    public static void Setup()
    {
        Debug.Log("[Setup8DirRun] Starting...");
        CreateAnimFolder();
        var sprites = LoadSprites();
        if (sprites == null) return;
        var clips = CreateRunClips(sprites);
        UpdateController(clips);
        UpdateMaterial();
        AssetDatabase.SaveAssets();
        Debug.Log("[Setup8DirRun] Done! 8-direction run clips created, controller updated, material configured.");
    }

    // ── Helpers ─────────────────────────────────────────────────────────────

    private static void CreateAnimFolder()
    {
        if (!AssetDatabase.IsValidFolder(AnimFolder))
            AssetDatabase.CreateFolder("Assets/Flynn/Animations", "Run8Dir");
    }

    private static Sprite[] LoadSprites()
    {
        var assets = AssetDatabase.LoadAllAssetsAtPath(SpriteSheetPath);
        var list = new List<Sprite>();
        foreach (var a in assets)
            if (a is Sprite s) list.Add(s);
        if (list.Count < 48)
        {
            Debug.LogError($"[Setup8DirRun] Expected 48 sprites in {SpriteSheetPath}, found {list.Count}. " +
                           "Make sure the sprite sheet is sliced (6 cols × 8 rows).");
            return null;
        }
        // Sort by name: run_0, run_1, ... run_47
        list.Sort((a, b) =>
        {
            int na = int.Parse(a.name.Substring(4));
            int nb = int.Parse(b.name.Substring(4));
            return na.CompareTo(nb);
        });
        return list.ToArray();
    }

    private static AnimationClip[] CreateRunClips(Sprite[] sprites)
    {
        var clips = new AnimationClip[8];
        for (int dir = 0; dir < 8; dir++)
        {
            string clipName = $"Flynn_Run_{DirectionNames[dir]}";
            string clipPath = $"{AnimFolder}/{clipName}.anim";

            // Check if already exists
            var existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(clipPath);
            if (existing != null)
            {
                AssetDatabase.DeleteAsset(clipPath);
            }

            var clip = new AnimationClip
            {
                name = clipName,
                frameRate = 12f,
                wrapMode = WrapMode.Loop
            };

            // Enable loop time
            var settings = AnimationUtility.GetAnimationClipSettings(clip);
            settings.loopTime = true;
            settings.loopBlend = false;
            AnimationUtility.SetAnimationClipSettings(clip, settings);

            // 6 sprites per row, row = dir
            var keyframes = new ObjectReferenceKeyframe[6];
            for (int frame = 0; frame < 6; frame++)
            {
                keyframes[frame] = new ObjectReferenceKeyframe
                {
                    time = frame / 12f,
                    value = sprites[dir * 6 + frame]
                };
            }

            var binding = new EditorCurveBinding
            {
                type = typeof(SpriteRenderer),
                path = "",
                propertyName = "m_Sprite"
            };

            AnimationUtility.SetObjectReferenceCurve(clip, binding, keyframes);

            AssetDatabase.CreateAsset(clip, clipPath);
            clips[dir] = clip;
            Debug.Log($"[Setup8DirRun] Created clip: {clipPath}");
        }
        return clips;
    }

    private static void UpdateController(AnimationClip[] runClips)
    {
        var controller = AssetDatabase.LoadAssetAtPath<AnimatorController>(ControllerPath);
        if (controller == null)
        {
            Debug.LogError($"[Setup8DirRun] Controller not found at {ControllerPath}");
            return;
        }

        // Update FacingDir parameter range isn't directly exposed; the BlendTree thresholds handle it.

        // Find the Run state and replace its BlendTree
        var sm = controller.layers[0].stateMachine;
        BlendTree runTree = null;
        AnimatorState runState = null;

        foreach (var state in sm.states)
        {
            if (state.state.name == "Run")
            {
                runState = state.state;
                runTree = state.state.motion as BlendTree;
                break;
            }
        }

        if (runState == null || runTree == null)
        {
            Debug.LogError("[Setup8DirRun] Could not find Run state with BlendTree in controller.");
            return;
        }

        // ── Build new 8-child Run BlendTree ──────────────────────────────
        var newRunTree = new BlendTree
        {
            name = "Run_Tree",
            blendType = BlendTreeType.Simple1D,
            blendParameter = "FacingDir",
            useAutomaticThresholds = false
        };

        for (int i = 0; i < 8; i++)
        {
            newRunTree.AddChild(runClips[i], (float)i);
        }

        runState.motion = newRunTree;

        // ── Update other BlendTrees for 8-direction FacingDir ────────────
        // For non-run trees, map diagonal directions to the nearest cardinal clip
        UpdateNonRunTrees(controller);

        EditorUtility.SetDirty(controller);
        Debug.Log("[Setup8DirRun] Controller updated with 8-direction Run_Tree.");
    }

    private static void UpdateNonRunTrees(AnimatorController controller)
    {
        var sm = controller.layers[0].stateMachine;

        foreach (var childState in sm.states)
        {
            var tree = childState.state.motion as BlendTree;
            if (tree == null) continue;
            if (tree.name == "Run_Tree") continue; // Already handled

            var oldMotions = tree.children;
            if (oldMotions.Length < 3) continue; // Need at least 3 to remap

            // oldMotions[0] = Down (threshold 0), [1] = Up (threshold 1), [2] = Left (threshold 2)
            // New mapping:
            // 0 Down       → oldMotions[0] (Down)
            // 1 DownLeft   → oldMotions[0] (Down)
            // 2 Left       → oldMotions[2] (Left)
            // 3 UpLeft     → oldMotions[2] (Left — side view closer)
            // 4 Up         → oldMotions[1] (Up)
            // 5 UpRight    → oldMotions[1] (Up)
            // 6 Right      → oldMotions[2] (Left — driver flips)
            // 7 DownRight  → oldMotions[0] (Down)

            var down = oldMotions[0].motion;
            var up   = oldMotions[1].motion;
            var left = oldMotions[2].motion;

            var newMotions = new ChildMotion[]
            {
                new ChildMotion { motion = down, threshold = 0f, timeScale = 1f, directBlendParameter = "", mirror = false },
                new ChildMotion { motion = down, threshold = 1f, timeScale = 1f, directBlendParameter = "", mirror = false },
                new ChildMotion { motion = left, threshold = 2f, timeScale = 1f, directBlendParameter = "", mirror = false },
                new ChildMotion { motion = left, threshold = 3f, timeScale = 1f, directBlendParameter = "", mirror = false },
                new ChildMotion { motion = up,   threshold = 4f, timeScale = 1f, directBlendParameter = "", mirror = false },
                new ChildMotion { motion = up,   threshold = 5f, timeScale = 1f, directBlendParameter = "", mirror = false },
                new ChildMotion { motion = left, threshold = 6f, timeScale = 1f, directBlendParameter = "", mirror = false },
                new ChildMotion { motion = down, threshold = 7f, timeScale = 1f, directBlendParameter = "", mirror = false },
            };

            tree.children = newMotions;
            tree.useAutomaticThresholds = false;

            EditorUtility.SetDirty(tree);
            Debug.Log($"[Setup8DirRun] Updated BlendTree: {tree.name} (3→8 thresholds)");
        }
    }

    private static void UpdateMaterial()
    {
        var mat = AssetDatabase.LoadAssetAtPath<Material>(MaterialPath);
        if (mat == null)
        {
            Debug.LogError($"[Setup8DirRun] Material not found at {MaterialPath}");
            return;
        }

        // Assign the normal map texture to the _BumpMap slot
        var normalTex = AssetDatabase.LoadAssetAtPath<Texture2D>(NormalMapPath);
        if (normalTex == null)
        {
            Debug.LogError($"[Setup8DirRun] Normal map texture not found at {NormalMapPath}");
            return;
        }

        mat.SetTexture("_BumpMap", normalTex);

        // Switch to URP/Lit shader if not already
        var urpLitShader = Shader.Find("Universal Render Pipeline/Lit");
        if (urpLitShader != null)
        {
            mat.shader = urpLitShader;
            Debug.Log("[Setup8DirRun] Shader switched to Universal Render Pipeline/Lit");
        }
        else
        {
            Debug.LogWarning("[Setup8DirRun] URP/Lit shader not found. Keeping current shader.");
        }

        // Ensure the material is set up for transparency (sprite-like)
        mat.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
        mat.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
        mat.SetInt("_ZWrite", 0);
        mat.SetFloat("_Surface", 1); // Transparent
        mat.SetInt("_Cull", (int)UnityEngine.Rendering.CullMode.Off); // Double-sided
        mat.SetFloat("_AlphaClip", 1); // Alpha clipping for crisp edges
        mat.SetFloat("_Cutoff", 0.3f);
        mat.SetFloat("_BumpScale", 1f);
        mat.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;

        EditorUtility.SetDirty(mat);
        Debug.Log("[Setup8DirRun] Material updated with normal map and URP Lit shader.");
    }
}

