/// <summary>
/// Reads SolarpunkCharacterController state and feeds the Animator on the Visual child.
/// 4-direction facing driven by FacingDir (int): 0=Down, 1=Up, 2=Left.
/// Right-side facing is handled by flipping the sprite and using the Left animation.
/// Camera-relative: "Down" = toward the camera.
/// </summary>

args.new_string:
/// <summary>
/// Reads SolarpunkCharacterController state and feeds the Animator on the Visual child.
/// 8-direction facing driven by FacingDir (float): 0=Down, 1=DownLeft, 2=Left,
/// 3=UpLeft, 4=Up, 5=UpRight, 6=Right, 7=DownRight.
/// Right-side facing uses explicit sprites (no flip needed for 8-dir run).
/// Non-run animations map diagonals to nearest cardinal and flip when needed.
/// Camera-relative: "Down" = toward the camera.
/// </summary>

args.old_string:
// Angle from Down (toward camera), counterclockwise = screen-left
float angle = Mathf.Atan2(-screenRight, -intoScreen) * Mathf.Rad2Deg;
if (angle < 0f) angle += 360f;

// Right-side facing → flip sprite and mirror angle to left side
bool flip = angle > 180f;
if (flip) angle = 360f - angle;

// 3 sectors: 0=Down, 1=Up, 2=Left (Right = flip + Left)
int dir;
if      (angle < 45f)  dir = 0; // Down
else if (angle < 135f) dir = 2; // Left
else                   dir = 1; // Up

// Only flip sprite for Left/Right directions — Down and Up are straight-on, no flip
bool flipLeft = (dir == 2) && flip;
_animator.SetFloat(FacingDirHash, dir);
if (_sprite != null) _sprite.flipX = flipLeft;

_lastFacingDir = dir;
_lastFlipX = flipLeft;

args.new_string:
// Angle from Down (toward camera), counterclockwise = screen-left
float angle = Mathf.Atan2(-screenRight, -intoScreen) * Mathf.Rad2Deg;
if (angle < 0f) angle += 360f;

// Right-side facing → mirror angle to left side for sector calc
bool flip = angle > 180f;
if (flip) angle = 360f - angle;

// 8 sectors: 0=Down, 1=DownLeft, 2=Left, 3=UpLeft, 4=Up, 5=UpRight, 6=Right, 7=DownRight
int dir;
if      (angle < 22.5f)  dir = 0; // Down
else if (angle < 67.5f)  dir = 1; // DownLeft / DownRight
else if (angle < 112.5f) dir = 2; // Left / Right
else if (angle < 157.5f) dir = 3; // UpLeft / UpRight
else                     dir = 4; // Up

// Map right-side angles to their FacingDir values
if (flip)
{
    // Mirror: DownLeft→DownRight(7), Left→Right(6), UpLeft→UpRight(5), Up stays(4), Down stays(0)
    dir = dir switch
    {
        1 => 7, // DownRight
        2 => 6, // Right
        3 => 5, // UpRight
        _ => dir
    };
}

// Flip sprite only for non-run animations that only have Left-facing sprites
// (directions 5, 6, 7 are right-side — only flip for non-run states)
bool flipSprite = (dir == 6); // Right-facing always flips for Left-only animations
_animator.SetFloat(FacingDirHash, dir);
if (_sprite != null) _sprite.flipX = flipSprite;

_lastFacingDir = dir;
_lastFlipX = flipSprite;

