using UnityEngine;
using UnityEditor;

var mat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Flynn/Materials/M_SpriteLit3D.mat");
if (mat == null) { Debug.LogError("Material not found!"); return; }

// Assign the normal map texture
var normalTex = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Flynn/Sprites/run_n.png");
if (normalTex == null) { Debug.LogError("Normal map not found!"); return; }

mat.SetTexture("_BumpMap", normalTex);
Debug.Log($"[Material] Assigned _BumpMap: {normalTex.name}");

// Switch to URP/Lit shader
var urpLit = Shader.Find("Universal Render Pipeline/Lit");
if (urpLit != null)
{
    mat.shader = urpLit;
    Debug.Log("[Material] Switched to Universal Render Pipeline/Lit");

    // Configure for transparent sprite-like rendering
    mat.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
    mat.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
    mat.SetInt("_ZWrite", 0);
    mat.SetFloat("_Surface", 1); // Transparent
    mat.SetInt("_Cull", (int)UnityEngine.Rendering.CullMode.Off); // Double-sided
    mat.SetFloat("_AlphaClip", 1);
    mat.SetFloat("_Cutoff", 0.3f);
    mat.SetFloat("_BumpScale", 1f);
    mat.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;
    Debug.Log("[Material] Configured transparency + alpha clip");
}
else
{
    Debug.LogWarning("[Material] URP/Lit shader not found — keeping current shader but assigned normal map");
}

EditorUtility.SetDirty(mat);
AssetDatabase.SaveAssets();
Debug.Log("[Material] Saved!");

