using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
using System.Collections.Generic;

// ═══════════════════════════════════════════════════════════════════════════
// 1. SLICE idle_n.png TO MATCH idle.png
// ═══════════════════════════════════════════════════════════════════════════
{
    var idleMeta = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Flynn/Sprites/idle.png");
    var idleNMeta = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Flynn/Sprites/idle_n.png");
    if (idleNMeta != null)
    {
        // Get the idle.png importer to read its slice rects
        var idleImporter = AssetImporter.GetAtPath("Assets/Flynn/Sprites/idle.png") as TextureImporter;
        var idleNImporter = AssetImporter.GetAtPath("Assets/Flynn/Sprites/idle_n.png") as TextureImporter;

        if (idleImporter != null && idleNImporter != null)
        {
            // Read spritesheet rects from idle.png
            var idleSheet = new List<SpriteRect>();
            idleImporter.GetSpriteSheetSprites(idleSheet); // This may not work directly

            // Alternative: load all sprites from idle.png to get rects
            var idleSprites = AssetDatabase.LoadAllAssetsAtPath("Assets/Flynn/Sprites/idle.png");
            var spriteData = new List<(string name, Rect rect)>();
            foreach (var a in idleSprites)
            {
                if (a is Sprite s)
                {
                    spriteData.Add((s.name, s.rect));
                }
            }
            spriteData.Sort((a, b) => int.Parse(a.name.Substring(5)).CompareTo(int.Parse(b.name.Substring(5))));

            Debug.Log($"[8Dir] idle.png has {spriteData.Count} sprites, will slice idle_n.png to match");

            // Now slice idle_n.png with the same rects
            idleNImporter.spriteImportMode = SpriteImportMode.Multiple;

            var spriteSheet = new List<SpriteRect>();
            for (int i = 0; i < spriteData.Count; i++)
            {
                var sd = spriteData[i];
                spriteSheet.Add(new SpriteRect
                {
                    name = sd.name.Replace("idle_", "idle_n_"),
                    rect = sd.rect,
                    alignment = 7,
                    pivot = new Vector2(0.5f, 0f),
                    border = new Vector4(0, 0, 0, 0),
                });
            }

            idleNImporter.SetSpriteSheetSprites(spriteSheet.ToArray());

            // Keep as normal map type
            idleNImporter.textureType = TextureImporterType.NormalMap;
            idleNImporter.sRGBTexture = false;
            idleNImporter.alphaSource = TextureImporterAlphaSource.None;
            idleNImporter.alphaIsTransparency = false;
            idleNImporter.spritePixelsPerUnit = 400;

            EditorUtility.SetDirty(idleNImporter);
            idleNImporter.SaveAndReimport();
            Debug.Log($"[8Dir] Sliced idle_n.png into {spriteData.Count} sprites");
        }
        else
        {
            Debug.LogError("[8Dir] Could not get importers for idle sprite sheets");
        }
    }
}

AssetDatabase.Refresh();
Debug.Log("[8Dir] idle_n.png reimport complete");

