                spriteSheet.Add(new SpriteRect
                {
                    name = sd.name.Replace("idle_", "idle_n_"),
                    rect = sd.rect,
                    alignment = 7,
                    pivot = new Vector2(0.5f, 0f),
                    border = new Vector4(0, 0, 0, 0),
                });
            }

            idleNImporter.SetSpriteSheetSprites(spriteSheet.ToArray());

            // Keep as normal map type
            idleNImporter.textureType = TextureImporterType.NormalMap;
            idleNImporter.sRGBTexture = false;
