using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
using System.Collections.Generic;
using System.Linq;

void SliceNormalMap(string diffusePath, string normalPath, string spriteNamePrefix, string normalPrefix)
{
    var diffuseSprites = AssetDatabase.LoadAllAssetsAtPath(diffusePath);
    var spriteData = new List<(string name, Rect rect)>();
    foreach (var a in diffuseSprites)
        if (a is Sprite s) spriteData.Add((s.name, s.rect));
    spriteData.Sort((a, b) => int.Parse(a.name.Substring(spriteNamePrefix.Length)).CompareTo(int.Parse(b.name.Substring(spriteNamePrefix.Length))));

    Debug.Log($"[8Dir] {diffusePath} has {spriteData.Count} sprites, slicing {normalPath} to match");

    var importer = AssetImporter.GetAtPath(normalPath) as TextureImporter;
    if (importer == null) { Debug.LogError($"No importer for {normalPath}"); return; }

    // Use SerializedObject to set sprite sheet rects
    var so = new SerializedObject(importer);
    so.Update();

    var spriteSheetProp = so.FindProperty("m_SpriteSheet.m_Sprites");
    spriteSheetProp.arraySize = spriteData.Count;

    for (int i = 0; i < spriteData.Count; i++)
    {
        var sd = spriteData[i];
        var elem = spriteSheetProp.GetArrayElementAtIndex(i);

        elem.FindPropertyRelative("m_Name").stringValue = normalPrefix + sd.name.Substring(spriteNamePrefix.Length);

        var rectProp = elem.FindPropertyRelative("m_Rect");
        rectProp.FindPropertyRelative("x").intValue = (int)sd.rect.x;
        rectProp.FindPropertyRelative("y").intValue = (int)sd.rect.y;
        rectProp.FindPropertyRelative("width").intValue = (int)sd.rect.width;
        rectProp.FindPropertyRelative("height").intValue = (int)sd.rect.height;

        elem.FindPropertyRelative("m_Alignment").intValue = 7;
        var pivotProp = elem.FindPropertyRelative("m_Pivot");
        pivotProp.FindPropertyRelative("x").floatValue = 0.5f;
        pivotProp.FindPropertyRelative("y").floatValue = 0f;

        var borderProp = elem.FindPropertyRelative("m_Border");
        borderProp.FindPropertyRelative("x").floatValue = 0;
        borderProp.FindPropertyRelative("y").floatValue = 0;
        borderProp.FindPropertyRelative("z").floatValue = 0;
        borderProp.FindPropertyRelative("w").floatValue = 0;
    }

    // Set sprite mode to multiple
    so.FindProperty("m_SpriteMode").intValue = 2;

    // Set texture type to Default (we need sprites)
    so.FindProperty("m_TextureType").intValue = 8; // Sprite
    so.FindProperty("m_SpritePixelsToUnits").floatValue = 400;
    so.FindProperty("m_AlphaSource").intValue = 4; // None
    so.FindProperty("m_AlphaIsTransparency").boolValue = false;
    so.FindProperty("m_sRGBTexture").boolValue = false;
    so.FindProperty("m_EnableMipMap").intValue = 0;

    so.ApplyModifiedPropertiesWithoutUndo();

    // Need to set to normal map type BUT keep sprites - use textureType 1 (NormalMap) + spriteMode 2
    // Actually, for secondary textures, the normal map needs to be a sprite sheet too
    // Set textureType back to Sprite (8) and it will work as secondary texture

    EditorUtility.SetDirty(importer);
    importer.SaveAndReimport();
    Debug.Log($"[8Dir] Sliced {normalPath} into {spriteData.Count} sprites via SerializedObject");
}

