using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
using System.Collections.Generic;

// ═══════════════════════════════════════════════════════════════════════════
// 1. CREATE 8-DIRECTION IDLE ANIMATION CLIPS
// ═══════════════════════════════════════════════════════════════════════════

var assets = AssetDatabase.LoadAllAssetsAtPath("Assets/Flynn/Sprites/idle.png");
var sprites = new List<Sprite>();
foreach (var a in assets)
    if (a is Sprite s) sprites.Add(s);
sprites.Sort((a, b) => int.Parse(a.name.Substring(5)).CompareTo(int.Parse(b.name.Substring(5))));
Debug.Log($"[8Dir] Loaded {sprites.Count} idle sprites");

if (!AssetDatabase.IsValidFolder("Assets/Flynn/Animations/Idle8Dir"))
    AssetDatabase.CreateFolder("Assets/Flynn/Animations", "Idle8Dir");

string[] dirNames = { "Down", "DownLeft", "Left", "UpLeft", "Up", "UpRight", "Right", "DownRight" };
var idleClips = new AnimationClip[8];

for (int dir = 0; dir < 8; dir++)
{
    string clipName = $"Flynn_Idle_{dirNames[dir]}";
    string clipPath = $"Assets/Flynn/Animations/Idle8Dir/{clipName}.anim";

    var existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(clipPath);
    if (existing != null) AssetDatabase.DeleteAsset(clipPath);

    var clip = new AnimationClip { name = clipName, frameRate = 12f };
    var settings = AnimationUtility.GetAnimationClipSettings(clip);
    settings.loopTime = true;
    AnimationUtility.SetAnimationClipSettings(clip, settings);

    var keyframes = new ObjectReferenceKeyframe[6];
    for (int frame = 0; frame < 6; frame++)
    {
        keyframes[frame] = new ObjectReferenceKeyframe
        {
            time = frame / 12f,
            value = sprites[dir * 6 + frame]
        };
    }

    var binding = new EditorCurveBinding
    {
        type = typeof(SpriteRenderer),
        path = "",
        propertyName = "m_Sprite"
    };

    AnimationUtility.SetObjectReferenceCurve(clip, binding, keyframes);
    AssetDatabase.CreateAsset(clip, clipPath);
    idleClips[dir] = clip;
    Debug.Log($"[8Dir] Created idle clip: {clipName}");
}

// ═══════════════════════════════════════════════════════════════════════════
// 2. UPDATE CONTROLLER: Replace Idle_Tree with 8-direction clips
// ═══════════════════════════════════════════════════════════════════════════

var controller = AssetDatabase.LoadAssetAtPath<AnimatorController>(
    "Assets/Flynn/Animations/Flynn_FrameAnimator.controller");
if (controller == null) { Debug.LogError("[8Dir] Controller not found!"); return; }

var sm = controller.layers[0].stateMachine;

// Find the Idle state and replace its BlendTree
foreach (var cs in sm.states)
{
    if (cs.state.name == "Idle")
    {
        var idleTree = new BlendTree
        {
            name = "Idle_Tree",
            blendType = BlendTreeType.Simple1D,
            blendParameter = "FacingDir",
            useAutomaticThresholds = false
        };
        for (int i = 0; i < 8; i++)
            idleTree.AddChild(idleClips[i], (float)i);

        cs.state.motion = idleTree;
        Debug.Log("[8Dir] Idle_Tree updated to 8 directions");
        break;
    }
}

EditorUtility.SetDirty(controller);
AssetDatabase.SaveAssets();
Debug.Log("[8Dir] Idle clips + controller updated!");

