using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

// Set up secondary textures on idle.png and run.png to link normal maps
void SetupSecondaryTextures(string diffusePath, string normalPath)
{
    var importer = AssetImporter.GetAtPath(diffusePath) as TextureImporter;
    if (importer == null) { Debug.LogError($"No importer for {diffusePath}"); return; }

    // Get the normal map GUID
    var normalGuid = AssetDatabase.AssetPathToGUID(normalPath);

    // Read existing secondary textures
    var secondaries = new List<TextureImporterSecondarySpriteTexture>();
    if (importer.secondarySpriteTextures != null)
        secondaries.AddRange(importer.secondarySpriteTextures);

    // Remove any existing _NormalMap entry
    secondaries.RemoveAll(s => s.name == "_NormalMap");

    // Add the normal map secondary texture
    secondaries.Add(new TextureImporterSecondarySpriteTexture
    {
        name = "_NormalMap",
        sprite = AssetDatabase.LoadAssetAtPath<Sprite>(normalPath)
    });

    importer.secondarySpriteTextures = secondaries.ToArray();

    EditorUtility.SetDirty(importer);
    importer.SaveAndReimport();
    Debug.Log($"[8Dir] Set up secondary _NormalMap for {diffusePath} → {normalPath}");
}

