using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

// Use SerializedObject to set secondary textures
void SetupSecondaryTextures(string diffusePath, string normalPath)
{
    var importer = AssetImporter.GetAtPath(diffusePath) as TextureImporter;
    if (importer == null) { Debug.LogError($"No importer for {diffusePath}"); return; }

    var normalTex = AssetDatabase.LoadAssetAtPath<Texture2D>(normalPath);
    if (normalTex == null) { Debug.LogError($"No normal map at {normalPath}"); return; }

    var so = new SerializedObject(importer);
    so.Update();

    var secTexProp = so.FindProperty("m_SecondarySpriteTextures");

    // Check if _NormalMap already exists
    int existingIdx = -1;
    for (int i = 0; i < secTexProp.arraySize; i++)
    {
        var nameProp = secTexProp.GetArrayElementAtIndex(i).FindPropertyRelative("m_Name");
        if (nameProp != null && nameProp.stringValue == "_NormalMap")
        {
            existingIdx = i;
            break;
        }
    }

    int targetIdx = existingIdx >= 0 ? existingIdx : secTexProp.arraySize;
    if (existingIdx < 0) secTexProp.arraySize++;

    var entry = secTexProp.GetArrayElementAtIndex(targetIdx);
    entry.FindPropertyRelative("m_Name").stringValue = "_NormalMap";
    entry.FindPropertyRelative("m_Sprite").objectReferenceValue = normalTex;

    so.ApplyModifiedPropertiesWithoutUndo();
    EditorUtility.SetDirty(importer);
    importer.SaveAndReimport();
    Debug.Log($"[8Dir] Set up secondary _NormalMap for {diffusePath}");
}

SetupSecondaryTextures("Assets/Flynn/Sprites/idle.png", "Assets/Flynn/Sprites/idle_n.png");
SetupSecondaryTextures("Assets/Flynn/Sprites/run.png", "Assets/Flynn/Sprites/run_n.png");

Debug.Log("[8Dir] Secondary textures configured!");

