using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

public static class SliceNormalMaps
{
    [MenuItem("Tools/Slice Normal Maps")]
    public static void Slice()
    {
        SliceOne("Assets/Flynn/Sprites/idle.png", "Assets/Flynn/Sprites/idle_n.png", "idle_", "idle_n_");
        SliceOne("Assets/Flynn/Sprites/run.png", "Assets/Flynn/Sprites/run_n.png", "run_", "run_n_");
        AssetDatabase.SaveAssets();
        Debug.Log("[SliceNormalMaps] Done!");
    }

    static void SliceOne(string diffusePath, string normalPath, string prefix, string normalPrefix)
    {
        var diffuseImporter = AssetImporter.GetAtPath(diffusePath) as TextureImporter;
        var normalImporter = AssetImporter.GetAtPath(normalPath) as TextureImporter;
        if (diffuseImporter == null || normalImporter == null) { Debug.LogError("Importer missing"); return; }

        // Read sprite rects from the diffuse sheet's meta data
        var so = new SerializedObject(diffuseImporter);
        so.Update();
        var srcSprites = so.FindProperty("m_SpriteSheet.m_Sprites");
        int count = srcSprites.arraySize;
        Debug.Log($"[Slice] {diffusePath} has {count} sprites");

        // Build SpriteRect array matching the diffuse
        var rects = new List<SpriteRect>();
        for (int i = 0; i < count; i++)
        {
            var elem = srcSprites.GetArrayElementAtIndex(i);
            var r = new SpriteRect
            {
                name = normalPrefix + elem.FindPropertyRelative("m_Name").stringValue.Substring(prefix.Length),
                rect = new Rect(
                    elem.FindPropertyRelative("m_Rect.x").intValue,
                    elem.FindPropertyRelative("m_Rect.y").intValue,
                    elem.FindPropertyRelative("m_Rect.width").intValue,
                    elem.FindPropertyRelative("m_Rect.height").intValue
                ),
                alignment = SpriteAlignment.BottomCenter,
                pivot = new Vector2(0.5f, 0f),
                border = new Vector4(0, 0, 0, 0),
            };
            rects.Add(r);
        }

        // Apply to the normal map importer
        normalImporter.spriteImportMode = SpriteImportMode.Multiple;
        normalImporter.SetSpriteSheetSprites(rects.ToArray());

        // Keep as sprite type (required for secondary texture reference)
        // but mark as non-sRGB for normal map data
        var nso = new SerializedObject(normalImporter);
        nso.Update();
        nso.FindProperty("m_TextureType").intValue = 8; // Sprite
        nso.FindProperty("m_SpriteMode").intValue = 2; // Multiple
        nso.FindProperty("m_SpritePixelsToUnits").floatValue = diffuseImporter.spritePixelsPerUnit;
        nso.FindProperty("m_sRGBTexture").boolValue = false;
        nso.FindProperty("m_AlphaSource").intValue = 4; // None
        nso.FindProperty("m_AlphaIsTransparency").boolValue = false;
        nso.FindProperty("m_EnableMipMap").intValue = 0;
        nso.ApplyModifiedPropertiesWithoutUndo();

        EditorUtility.SetDirty(normalImporter);
        normalImporter.SaveAndReimport();
        Debug.Log($"[Slice] Sliced {normalPath} into {rects.Count} sprites");
    }
}

